'use client';

import React, { useState, useEffect } from 'react';
import { KDSOrder, SLAState } from '../../types/kds';
import { getSLAState, formatDuration } from '../../utils/slaUtils';

interface TicketTimerProps {
    order: KDSOrder;
}

export const TicketTimer: React.FC<TicketTimerProps> = ({ order }) => {
    const [slaState, setSlaState] = useState<SLAState>(getSLAState(order));
    const [elapsedSeconds, setElapsedSeconds] = useState<number>(0);

    useEffect(() => {
        // Initial calculation
        const updateTime = () => {
            const createdAt = new Date(order.createdAt).getTime();
            const now = Date.now();
            const currentElapsed = Math.floor((now - createdAt) / 1000);
            setElapsedSeconds(currentElapsed);

            const currentState = getSLAState(order);
            setSlaState(currentState);
        };

        updateTime();
        const interval = setInterval(updateTime, 1000);

        return () => clearInterval(interval);
    }, [order]);

    const getTimerDisplay = () => {
        const totalPrepSeconds = (order.prepTimeMinutes || 0) * 60;
        const remaining = totalPrepSeconds - elapsedSeconds;

        return {
            text: formatDuration(remaining),
            isNegative: remaining < 0
        };
    };

    const timerData = getTimerDisplay();

    const getSLAColor = () => {
        switch (slaState) {
            case 'OVERDUE': return 'text-red-600';
            case 'WARNING': return 'text-orange-500';
            default: return 'text-slate-800';
        }
    };

    return (
        <div className={`flex flex-col items-end ${slaState === 'OVERDUE' ? 'animate-pulse-subtle' : ''}`}>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">TIMER</span>
            <span className={`text-2xl font-black tabular-nums transition-colors duration-300 ${getSLAColor()}`}>
                {timerData.isNegative ? '-' : ''}{timerData.text}
            </span>
        </div>
    );
};
