'use client';

import React, { useState } from 'react';
import { X, Clock, AlertTriangle } from 'lucide-react';

interface DelayOrderModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (minutes: number, reason: string) => void;
    orderNumber: string;
}

export const DelayOrderModal: React.FC<DelayOrderModalProps> = ({
    isOpen,
    onClose,
    onConfirm,
    orderNumber,
}) => {
    const [minutes, setMinutes] = useState<number>(10);
    const [reason, setReason] = useState<string>('');
    const [customValue, setCustomValue] = useState<string>('');

    if (!isOpen) return null;

    const quickOptions = [5, 10, 15];

    const handleConfirm = () => {
        const finalMinutes = customValue ? parseInt(customValue, 10) : minutes;
        if (isNaN(finalMinutes) || finalMinutes < 0) return;
        onConfirm(finalMinutes, reason);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-200 animate-in zoom-in-95 duration-300">
                {/* Header */}
                <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div className="flex items-center gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-red-50 flex items-center justify-center border border-red-100">
                            <AlertTriangle className="w-8 h-8 text-red-500" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-slate-900 leading-tight">Delay Order #{orderNumber}</h2>
                            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">Select preparation extension</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="w-12 h-12 rounded-xl flex items-center justify-center text-slate-400 hover:bg-slate-200 hover:text-slate-600 transition-all active:scale-90"
                    >
                        <X size={24} />
                    </button>
                </div>

                <div className="p-8 space-y-8">
                    {/* Quick Minutes Options */}
                    <div className="grid grid-cols-3 gap-4">
                        {quickOptions.map((opt) => (
                            <button
                                key={opt}
                                onClick={() => {
                                    setMinutes(opt);
                                    setCustomValue('');
                                }}
                                className={`h-20 rounded-2xl flex flex-col items-center justify-center gap-1 transition-all border-2 font-black ${minutes === opt && !customValue
                                        ? 'bg-slate-900 border-slate-900 text-white shadow-xl shadow-slate-200 scale-[1.02]'
                                        : 'bg-white border-slate-200 text-slate-600 hover:border-slate-400 hover:bg-slate-50'
                                    }`}
                            >
                                <span className="text-2xl">+{opt}</span>
                                <span className="text-[10px] uppercase tracking-widest opacity-60">MINUTES</span>
                            </button>
                        ))}
                    </div>

                    {/* Custom Input */}
                    <div className="space-y-3">
                        <label className="text-xs font-black text-slate-400 uppercase tracking-widest pl-1">Custom Extension</label>
                        <div className="relative">
                            <Clock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 w-6 h-6" />
                            <input
                                type="number"
                                placeholder="Enter minutes..."
                                value={customValue}
                                onChange={(e) => {
                                    setCustomValue(e.target.value);
                                    setMinutes(0);
                                }}
                                className="w-full h-16 pl-14 pr-6 bg-slate-50 border-2 border-slate-200 rounded-2xl text-xl font-black focus:outline-none focus:border-slate-900 focus:bg-white transition-all placeholder:text-slate-300"
                            />
                        </div>
                    </div>

                    {/* Reason Field */}
                    <div className="space-y-3">
                        <label className="text-xs font-black text-slate-400 uppercase tracking-widest pl-1">Delay Reason (Optional)</label>
                        <textarea
                            placeholder="e.g., Deep fryer maintenance, Missing ingredients..."
                            value={reason}
                            onChange={(e) => setReason(e.target.value)}
                            className="w-full h-32 p-6 bg-slate-50 border-2 border-slate-200 rounded-2xl text-lg font-bold focus:outline-none focus:border-slate-900 focus:bg-white transition-all placeholder:text-slate-300 resize-none"
                        />
                    </div>
                </div>

                {/* Footer */}
                <div className="p-8 bg-slate-50 border-t border-slate-100 flex gap-4">
                    <button
                        onClick={onClose}
                        className="flex-1 h-16 rounded-2xl border-2 border-slate-200 text-slate-600 font-black uppercase tracking-widest text-sm hover:bg-slate-200 transition-all active:scale-95"
                    >
                        Cancel
                    </button>
                    <button
                        onClick={handleConfirm}
                        className="flex-1 h-16 rounded-2xl bg-red-600 text-white font-black uppercase tracking-widest text-sm shadow-xl shadow-red-200 hover:bg-red-700 transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                        Confirm Delay
                    </button>
                </div>
            </div>
        </div>
    );
};
