'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Volume2, VolumeX, Settings2, Bell, AlertTriangle, Clock } from 'lucide-react';
import { useSoundStore } from '../../store/useSoundStore';

export const SoundSettings: React.FC = () => {
    const { settings, setVolume, toggleEvent } = useSoundStore();
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const totalEnabled = [settings.newOrder, settings.delayed, settings.overdue].filter(Boolean).length;

    return (
        <div className="relative" ref={containerRef}>
            <button
                className={`kds-header-btn transition-colors ${isOpen ? 'bg-slate-700' : ''}`}
                onClick={() => setIsOpen(!isOpen)}
                title="Sound Settings"
            >
                {settings.volume === 0 || totalEnabled === 0 ? <VolumeX size={28} /> : <Volume2 size={28} />}
                {totalEnabled > 0 && (
                    <span className="absolute -top-1 -right-1 w-4 h-4 bg-blue-500 rounded-full text-[10px] flex items-center justify-center font-black">
                        {totalEnabled}
                    </span>
                )}
            </button>

            {isOpen && (
                <div className="absolute right-0 mt-3 w-80 bg-slate-800 border border-slate-700 rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-800/50">
                        <h3 className="text-xs font-black uppercase tracking-widest text-slate-300 flex items-center gap-2">
                            <Settings2 size={14} />
                            Audio Configuration
                        </h3>
                    </div>

                    <div className="p-6 space-y-8">
                        {/* Volume Control */}
                        <div className="space-y-4">
                            <div className="flex justify-between items-center text-[10px] font-black uppercase text-slate-400">
                                <span>Master Volume</span>
                                <span>{Math.round(settings.volume * 100)}%</span>
                            </div>
                            <input
                                type="range"
                                min="0"
                                max="1"
                                step="0.01"
                                value={settings.volume}
                                onChange={(e) => setVolume(parseFloat(e.target.value))}
                                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            />
                        </div>

                        {/* Event Toggles */}
                        <div className="space-y-3">
                            <div className="text-[10px] font-black uppercase text-slate-400 mb-4">Event Alerts</div>

                            <ToggleItem
                                Icon={Bell}
                                label="New Orders"
                                active={settings.newOrder}
                                onClick={() => toggleEvent('newOrder')}
                                color="text-blue-400"
                            />

                            <ToggleItem
                                Icon={AlertTriangle}
                                label="Delayed Orders"
                                active={settings.delayed}
                                onClick={() => toggleEvent('delayed')}
                                color="text-orange-400"
                            />

                            <ToggleItem
                                Icon={Clock}
                                label="SLA Breach (Overdue)"
                                active={settings.overdue}
                                onClick={() => toggleEvent('overdue')}
                                color="text-red-400"
                            />
                        </div>
                    </div>

                    <div className="p-4 bg-slate-900/50 text-center">
                        <p className="text-[9px] font-bold text-slate-500 uppercase tracking-tighter">
                            Settings persist across sessions
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

interface ToggleProps {
    Icon: any;
    label: string;
    active: boolean;
    onClick: () => void;
    color: string;
}

const ToggleItem: React.FC<ToggleProps> = ({ Icon, label, active, onClick, color }) => (
    <button
        onClick={onClick}
        className={`w-full flex items-center justify-between p-3 rounded-xl transition-all duration-200 ${active ? 'bg-slate-700/50 border border-slate-600' : 'bg-transparent border border-transparent opacity-50 grayscale'
            }`}
    >
        <div className="flex items-center gap-3">
            <div className={`p-2 rounded-lg bg-slate-800 ${active ? color : 'text-slate-500'}`}>
                <Icon size={18} />
            </div>
            <span className="text-xs font-black text-slate-200">{label}</span>
        </div>
        <div className={`w-8 h-4 rounded-full relative transition-colors duration-200 ${active ? 'bg-blue-500' : 'bg-slate-600'}`}>
            <div className={`absolute top-1 w-2 h-2 rounded-full bg-white transition-all duration-200 ${active ? 'right-1' : 'left-1'}`} />
        </div>
    </button>
);
